<template>
  <view class="orders-page" :style="$themeStyle"><scroll-view scroll-x class="tabs"><view class="tab-row"><text v-for="(t,i) in tabs" :key="t" :class="{active:active===i}" @tap="active=i">{{t}}</text></view></scroll-view>
    <view v-if="filtered.length" class="orders"><view v-for="order in filtered" :key="order.id" class="order card"><view class="between order-head"><text>WILD MARKET</text><text class="accent">{{order.status}}</text></view><view v-for="item in order.items" :key="item.key||item.id" class="order-item"><view class="art item-art" :class="'art-'+item.tone"><image v-if="item.image" class="product-image" :src="item.image" mode="aspectFill"/><text v-else class="art-icon">{{item.cover}}</text></view><view><text>{{item.title}}</text><text>{{item.subtitle}}　×{{item.quantity}}</text></view><text class="price">{{item.price}}</text></view><view class="order-total">共 {{count(order)}} 件　实付 <text class="price">{{order.total}}</text></view><view class="buttons"><button class="btn-ghost" @tap="service">联系客服</button><button v-if="order.status==='待付款'" class="dark" @tap="pay(order)">去支付</button><button v-else class="dark" @tap="again(order)">再次购买</button></view></view></view>
    <view v-else class="empty"><view class="empty-icon">📦</view><view>这里暂时没有订单</view><button class="btn-primary empty-btn" @tap="home">去逛逛</button></view>
  </view>
</template>
<script setup>
import{ref,computed}from'vue';import{onLoad}from'@dcloudio/uni-app';import{products}from'../../data/mock';const tabs=['全部','待付款','待发货','待收货','待评价'],active=ref(0);const sample={id:'WM26100618',status:'待收货',total:'9010.00',items:[{...products[0],quantity:1,subtitle:products[0].specs[0]},{...products[2],quantity:1,subtitle:products[2].specs[0]}]};const orders=ref(uni.getStorageSync('demo_orders')||[sample]);onLoad(o=>active.value=Number(o.tab||0));const filtered=computed(()=>active.value===0?orders.value:orders.value.filter(v=>v.status===tabs[active.value]));const count=o=>o.items.reduce((s,v)=>s+v.quantity,0);const home=()=>uni.switchTab({url:'/pages/home/home'});const service=()=>uni.navigateTo({url:'/pages/service/service'});const pay=o=>{uni.setStorageSync('pending_order',o);uni.navigateTo({url:'/pages/payment/payment'})};const again=o=>{uni.setStorageSync('buy_now',o.items);uni.navigateTo({url:'/pages/checkout/checkout?from=buy'})}
</script>
<style scoped>
.orders-page{padding-bottom:40rpx}.tabs{white-space:nowrap;background:#fff}.tab-row{display:inline-flex;min-width:100%;justify-content:space-around}.tab-row text{padding:26rpx 25rpx;position:relative;color:var(--muted)}.tab-row .active{color:var(--ink);font-weight:700}.tab-row .active::after{content:'';position:absolute;bottom:0;left:35%;width:30%;height:5rpx;background:var(--ink)}.orders{padding:24rpx}.order{padding:28rpx;margin-bottom:22rpx}.order-head{padding-bottom:20rpx;font-weight:700}.order-item{display:flex;padding:16rpx 0;border-top:1rpx solid var(--line);align-items:center}.item-art{width:120rpx;height:120rpx;border-radius:15rpx;margin-right:18rpx}.item-art .art-icon{font-size:48rpx}.order-item>view:nth-child(2){flex:1;min-width:0}.order-item>view:nth-child(2) text{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.order-item>view:nth-child(2) text+text{font-size:20rpx;color:var(--muted);margin-top:10rpx}.order-total{text-align:right;padding-top:18rpx}.buttons{display:flex;justify-content:flex-end;gap:14rpx;margin-top:22rpx}.buttons button{margin:0;height:66rpx;font-size:22rpx;border-radius:34rpx;line-height:1;padding:0 25rpx;display:flex;align-items:center;justify-content:center}.buttons .dark{background:var(--ink);color:#fff}.empty-btn{width:260rpx;margin-top:40rpx}
</style>
